/**
 * Campaign map — a 16-bit overworld the disciples walk, bottom to top.
 *
 * The land is one painted image (assets/map/overworld.png) generated by
 * scripts/map/build_overworld.py, which also writes each node's position to
 * src/campaign/overworld.json. This screen scales the image to the screen
 * width and lays live node markers over it. Node states:
 *   - completed: gold marker with a star
 *   - current:   pulsing marker, the three heroes standing on it
 *   - available: unlocked but off the frontier (gap-y progress data)
 *   - locked:    dark marker, 🔒, tagline replaced by an unlock hint
 *
 * Tapping an unlocked node plays its cutscene every time (Skip is always
 * on screen), then goes to setup with that node's preset. Completed nodes stay playable.
 *
 * Adding a node: paint its region in the map script and re-run it (see the
 * script's header). A test checks every campaign preset has a position.
 */
import { useRouter } from 'expo-router';
import { useEffect, useRef, useState } from 'react';
import {
  Animated,
  Image,
  LayoutChangeEvent,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import { theme } from '../src/components/theme';
import { RULE_PRESETS, PRESET_ORDER } from '../src/campaign/presets';
import { MAP_SCENES, DEFAULT_SCENE } from '../src/campaign/mapMeta';
import { isUnlocked, useCampaignStore } from '../src/store/campaignStore';
import { CINEMATICS, ENDING_ID } from '../src/campaign/story';
import OVERWORLD from '../src/campaign/overworld.json';

const MAP_IMAGE = require('../assets/map/overworld.png');
const HEROES_IMAGE = require('../assets/map/heroes.png');
/** heroes.png's size, in the same units as the map image. */
const HEROES_W = OVERWORLD.heroes.width;
const HEROES_H = OVERWORLD.heroes.height;

const MARKER = 40;
const LABEL_W = 150;

type NodeState = 'completed' | 'current' | 'available' | 'locked';
type NodePos = { x: number; y: number; side: 'left' | 'right' };
const NODE_POS = OVERWORLD.nodes as Record<string, NodePos>;
const TOWER = OVERWORLD.tower;

export default function CampaignScreen() {
  const router = useRouter();
  const completed = useCampaignStore((s) => s.completed);
  const scrollRef = useRef<ScrollView>(null);
  const [width, setWidth] = useState(0);
  const [viewportH, setViewportH] = useState(0);

  // First unlocked-but-not-completed preset is "current".
  const currentId =
    PRESET_ORDER.find((id) => isUnlocked(completed, id) && !completed[id]) ??
    null;
  const doneCount = PRESET_ORDER.filter((id) => completed[id]).length;
  const allDone = doneCount === PRESET_ORDER.length;
  const playEnding = () =>
    router.push({ pathname: '/cinematic', params: { preset: ENDING_ID } });

  const stateFor = (id: string): NodeState => {
    if (completed[id]) return 'completed';
    if (id === currentId) return 'current';
    return isUnlocked(completed, id) ? 'available' : 'locked';
  };

  // Map units → screen points. The image is drawn at the full screen width.
  const k = width / OVERWORLD.width;
  const mapH = OVERWORLD.height * k;

  // Open the map centred on where the heroes stand (the frontier, or the
  // last node once the campaign is complete).
  const focusId = currentId ?? PRESET_ORDER[PRESET_ORDER.length - 1];
  useEffect(() => {
    if (!width || !viewportH) return;
    const pos = NODE_POS[focusId];
    if (!pos) return;
    const y = Math.max(0, Math.min(pos.y * k - viewportH / 2, mapH - viewportH));
    scrollRef.current?.scrollTo({ y, animated: false });
  }, [width, viewportH, focusId, k, mapH]);

  const onLayout = (e: LayoutChangeEvent) => {
    setWidth(e.nativeEvent.layout.width);
    setViewportH(e.nativeEvent.layout.height);
  };

  return (
    <View style={styles.container}>
      <Text style={styles.progress}>
        {allDone
          ? `🏆 All ${doneCount} tables restored. Something stirs beyond the fog…`
          : `${doneCount} / ${PRESET_ORDER.length} tables restored`}
      </Text>
      <View style={styles.viewport} onLayout={onLayout}>
        {width > 0 && (
          <ScrollView ref={scrollRef}>
            <View style={{ width, height: mapH }}>
              <Image
                source={MAP_IMAGE}
                style={{ width, height: mapH }}
                resizeMode="stretch"
                accessibilityIgnoresInvertColors
              />
              {PRESET_ORDER.map((id, i) => {
                const pos = NODE_POS[id];
                if (!pos) return null; // not painted yet; see the map script
                const prevName =
                  i > 0 ? RULE_PRESETS[PRESET_ORDER[i - 1]].name : null;
                return (
                  <MapNode
                    key={id}
                    x={pos.x * k}
                    y={pos.y * k}
                    mapWidth={width}
                    preset={RULE_PRESETS[id]}
                    scene={MAP_SCENES[id] ?? DEFAULT_SCENE}
                    state={stateFor(id)}
                    unlockHint={prevName ? `Beat ${prevName} to unlock` : null}
                    onPress={() => {
                      // Every visit plays the node's cutscene (Skip is on
                      // screen), which continues to setup itself.
                      router.push({
                        pathname: CINEMATICS[id] ? '/cinematic' : '/setup',
                        params: { preset: id },
                      });
                    }}
                  />
                );
              })}
              {/* Once every table is restored, Chris's tower (painted
                  scenery) replays the ending. Not a node: nothing to play
                  there yet. */}
              {allDone && (
                <>
                  <Pressable
                    onPress={playEnding}
                    accessibilityRole="button"
                    accessibilityLabel="The tower beyond the fog. Replay the ending."
                    style={{
                      position: 'absolute',
                      left: (TOWER.x - TOWER.width / 2) * k,
                      top: (TOWER.y - TOWER.height / 2) * k,
                      width: TOWER.width * k,
                      height: TOWER.height * k,
                    }}
                  />
                  <Pressable
                    onPress={playEnding}
                    importantForAccessibility="no-hide-descendants"
                    accessibilityElementsHidden
                    style={[
                      styles.label,
                      {
                        left: Math.max(6, TOWER.x * k - LABEL_W / 2),
                        top: (TOWER.y + TOWER.height / 2) * k + 6,
                      },
                    ]}
                  >
                    <Text style={styles.labelName}>To be continued…</Text>
                    <Text style={styles.labelTagline}>Tap the tower to see the ending again</Text>
                  </Pressable>
                </>
              )}
              {NODE_POS[focusId] && (
                <View
                  pointerEvents="none"
                  style={{
                    position: 'absolute',
                    left: NODE_POS[focusId].x * k - (HEROES_W * k) / 2,
                    top: NODE_POS[focusId].y * k - MARKER / 2 - HEROES_H * k + 2,
                  }}
                >
                  <Image
                    source={HEROES_IMAGE}
                    accessibilityLabel="Erich, Nick and Garrett"
                    style={{ width: HEROES_W * k, height: HEROES_H * k }}
                  />
                </View>
              )}
            </View>
          </ScrollView>
        )}
      </View>
    </View>
  );
}

// ─── Node marker + label ─────────────────────────────────────────────────────

function MapNode({
  x,
  y,
  mapWidth,
  preset,
  scene,
  state,
  unlockHint,
  onPress,
}: {
  x: number;
  y: number;
  mapWidth: number;
  preset: (typeof RULE_PRESETS)[string];
  scene: (typeof MAP_SCENES)[string];
  state: NodeState;
  unlockHint: string | null;
  onPress: () => void;
}) {
  const locked = state === 'locked';
  const pulse = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    if (state !== 'current') return;
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(pulse, { toValue: 1.15, duration: 700, useNativeDriver: true }),
        Animated.timing(pulse, { toValue: 1, duration: 700, useNativeDriver: true }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [state, pulse]);

  // The label hangs under the node, clear of the landmark beside it.
  const labelLeft = Math.max(6, Math.min(x - LABEL_W / 2, mapWidth - LABEL_W - 6));

  return (
    <>
      <Pressable
        onPress={locked ? undefined : onPress}
        disabled={locked}
        accessibilityRole="button"
        accessibilityState={{ disabled: locked }}
        accessibilityLabel={
          locked
            ? `${preset.name}. Locked. ${unlockHint ?? ''}`
            : `${preset.name}. ${state === 'completed' ? 'Completed.' : ''} Tap to play.`
        }
        hitSlop={10}
        style={{ position: 'absolute', left: x - MARKER / 2, top: y - MARKER / 2 }}
      >
        <Animated.View
          style={[
            styles.marker,
            { transform: [{ scale: state === 'current' ? pulse : 1 }] },
            locked
              ? styles.markerLocked
              : state === 'completed'
              ? styles.markerDone
              : { backgroundColor: scene.color },
            state === 'current' && styles.markerCurrent,
          ]}
        >
          <Text style={styles.markerText}>
            {locked ? '🔒' : state === 'completed' ? '★' : scene.emoji}
          </Text>
        </Animated.View>
      </Pressable>
      <Pressable
        onPress={locked ? undefined : onPress}
        disabled={locked}
        accessibilityElementsHidden
        importantForAccessibility="no-hide-descendants"
        style={[
          styles.label,
          { left: labelLeft, top: y + MARKER / 2 + 8 },
        ]}
      >
        <Text style={[styles.labelName, locked && styles.labelNameLocked]} numberOfLines={1}>
          {preset.name}
        </Text>
        <Text style={styles.labelTagline} numberOfLines={2}>
          {locked ? unlockHint ?? 'Locked' : scene.tagline}
        </Text>
      </Pressable>
    </>
  );
}

// ─── Styles ──────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#3880e8', // the map's sea, so edges blend while loading
  },
  viewport: {
    flex: 1,
  },
  progress: {
    color: theme.color.textMuted,
    textAlign: 'center',
    fontSize: 13,
    letterSpacing: 0.5,
    paddingVertical: 10,
    backgroundColor: theme.color.feltBgDark,
  },
  marker: {
    width: MARKER,
    height: MARKER,
    borderRadius: 8,
    borderWidth: 3,
    borderColor: '#181820',
    alignItems: 'center',
    justifyContent: 'center',
  },
  markerDone: {
    backgroundColor: '#f8c830',
  },
  markerLocked: {
    backgroundColor: '#3a3a48',
    borderColor: '#181820',
  },
  markerCurrent: {
    borderColor: '#f8f8f8',
  },
  markerText: {
    fontSize: 18,
    color: '#3a2c00',
    fontWeight: '800',
  },
  label: {
    position: 'absolute',
    width: LABEL_W,
    paddingVertical: 5,
    paddingHorizontal: 8,
    borderRadius: 4,
    borderWidth: 2,
    borderColor: '#181820',
    backgroundColor: 'rgba(24,24,40,0.82)',
    alignItems: 'center',
  },
  labelName: {
    color: '#f8f8f8',
    fontWeight: '800',
    fontSize: 13,
  },
  labelNameLocked: {
    color: '#a8a8b8',
  },
  labelTagline: {
    textAlign: 'center',
    color: '#d8d8e0',
    fontSize: 10,
    marginTop: 1,
  },
});
